// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    L1Block c;
    bool public mutObserver;

    function setUp() public {
        c = new L1Block();
    }

    function _test(address caller, uint64 newNumber) internal {
        uint64 before;
        try c.number() returns (uint64 __r) { before = __r; } catch { return; }
        mutObserver = false;
        if (caller != 0xDeaDDEaDDeAdDeAdDEAdDEaddeAddEAdDEAd0001) {
            mutObserver = true;
        }
        try c.setL1BlockValues(newNumber, 0, 0, bytes32(0), 0, bytes32(0), 0, 0) {} catch { return; }
        uint64 afterVal;
        try c.number() returns (uint64 __r) { afterVal = __r; } catch { return; }
        assertTrue(!mutObserver || (afterVal == before));
    }

    function testFuzz_test(address caller, uint64 newNumber) public {
        _test(caller, newNumber);
    }

    receive() external payable {}
}
